/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Schema, Either } from 'effect';
import { manifestSchema } from './dist/partners/schema.js';
import { importManifest } from './dist/partners/decode.js';
const parcel = { reference: ' ref ', grams: 1, service: 'standard', extra: {} };
const input = { partner: ' partner ', parcels: [parcel], extra: {} };
const expected = { partner: 'partner', parcels: [{ reference: 'ref', grams: 1, service: 'standard' }] };
const decoded = Schema.decodeUnknownEither(manifestSchema)(input);
assert(Either.isRight(decoded));
assert.deepEqual(decoded.right, expected);
const imported = importManifest(input);
assert.deepEqual(imported, { ok: true, manifest: expected });
assert.notEqual(imported.manifest, input);
assert.notEqual(imported.manifest.parcels, input.parcels);
assert.notEqual(imported.manifest.parcels[0], parcel);
assert.equal(parcel.reference, ' ref ');
const invalid = [undefined, null, [], 1, true, 'x', {}, {partner: ' ', parcels: [parcel]}, {partner: 'p', parcels: []}, {partner: 'p', parcels: [parcel, {...parcel, reference: 'ref'}]}];
for (const grams of [undefined, '1', null, 0, -1, 1.5, NaN, Infinity, -Infinity]) invalid.push({partner: 'p', parcels: [{...parcel, grams}]});
for (const reference of [undefined, null, 1, ' ']) invalid.push({partner: 'p', parcels: [{...parcel, reference}]});
for (const service of [undefined, null, 1, 'priority', ' standard ']) invalid.push({partner: 'p', parcels: [{...parcel, service}]});
for (const value of invalid) {
  assert(Either.isLeft(Schema.decodeUnknownEither(manifestSchema)(value)));
  assert.deepEqual(importManifest(value), {ok: false, reason: 'invalid-manifest'});
}
console.log('Direct schema/importer boundary checks passed');
JS"

