changes.after:
import { Schema } from "effect";
import type { PartnerManifest } from "./types.js";
const nonblankString = Schema.Trim.pipe(Schema.nonEmptyString());
const parcelSchema = Schema.Struct({
  reference: nonblankString,
  grams: Schema.Number.pipe(Schema.filter(value => Number.isFinite(value) && Number.isInteger(value) && value > 0)),
  service: Schema.Literal("standard", "express"),
});

export const manifestSchema: Schema.Schema<PartnerManifest> = Schema.Struct({
  partner: nonblankString,
  parcels: Schema.Array(parcelSchema).pipe(
    Schema.minItems(1),
    Schema.filter(parcels => new Set(parcels.map(parcel => parcel.reference)).size === parcels.length),
  ),
});
